mkdir -p /app/output && cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Global Aid Alliance — Together We Respond</title>
  <meta name="description" content="Global Aid Alliance delivers disaster relief, emergency assistance, and community resilience programs worldwide." />
  <style>
    :root {
      --red-900: #8e1b1b;
      --red-700: #b42323;
      --red-600: #c62828;
      --navy-900: #102a43;
      --navy-700: #1f3e63;
      --gray-50: #faf9f7;
      --gray-100: #f3f1ee;
      --gray-200: #e8e4df;
      --gray-600: #5c5a57;
      --gray-800: #2f2d2b;
      --white: #ffffff;
      --radius: 14px;
      --shadow-sm: 0 4px 14px rgba(0, 0, 0, 0.08);
      --shadow-md: 0 16px 30px rgba(16, 42, 67, 0.12);
      --container: min(1140px, 92vw);
    }

    * { box-sizing: border-box; }

    html, body {
      margin: 0;
      padding: 0;
      font-family: "Inter", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      color: var(--gray-800);
      background: var(--white);
      scroll-behavior: smooth;
    }

    h1, h2, h3 {
      margin: 0 0 0.75rem;
      line-height: 1.15;
      color: var(--navy-900);
      letter-spacing: -0.02em;
      font-family: "Manrope", "Inter", "Segoe UI", sans-serif;
    }

    p { margin: 0 0 1rem; line-height: 1.65; }
    a { color: inherit; text-decoration: none; }

    .container {
      width: var(--container);
      margin-inline: auto;
    }

    .topbar {
      position: sticky;
      top: 0;
      z-index: 30;
      background: rgba(255,255,255,.96);
      border-bottom: 1px solid var(--gray-200);
      backdrop-filter: blur(8px);
    }

    .header-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      min-height: 76px;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: .75rem;
      font-weight: 800;
      color: var(--navy-900);
    }

    .brand-mark {
      width: 42px;
      height: 42px;
      border-radius: 10px;
      background: linear-gradient(145deg, var(--red-700), var(--red-900));
      display: grid;
      place-items: center;
      color: var(--white);
      font-weight: 900;
      box-shadow: var(--shadow-sm);
    }

    .desktop-nav {
      display: flex;
      align-items: center;
      gap: 1.25rem;
      font-weight: 600;
      color: var(--navy-700);
    }

    .desktop-nav a:hover,
    .desktop-nav a:focus-visible { color: var(--red-700); }

    .btn {
      border: 0;
      border-radius: 999px;
      padding: .75rem 1.25rem;
      font-weight: 700;
      cursor: pointer;
      transition: transform .2s ease, background .2s ease, box-shadow .2s ease;
    }

    .btn:hover,
    .btn:focus-visible {
      transform: translateY(-1px);
      box-shadow: var(--shadow-sm);
    }

    .btn-primary {
      background: var(--red-700);
      color: var(--white);
    }

    .btn-primary:hover,
    .btn-primary:focus-visible { background: var(--red-900); }

    .btn-secondary {
      background: var(--navy-900);
      color: var(--white);
    }

    .menu-toggle {
      display: none;
      border: 1px solid var(--gray-200);
      background: var(--white);
      border-radius: 10px;
      width: 44px;
      height: 44px;
      align-items: center;
      justify-content: center;
      cursor: pointer;
    }

    .menu-toggle span,
    .menu-toggle span::before,
    .menu-toggle span::after {
      display: block;
      width: 20px;
      height: 2px;
      background: var(--navy-900);
      position: relative;
      content: "";
      transition: transform .2s ease;
    }

    .menu-toggle span::before { position: absolute; top: -6px; }
    .menu-toggle span::after { position: absolute; top: 6px; }

    .mobile-drawer {
      position: fixed;
      inset: 76px 0 auto 0;
      background: var(--white);
      border-bottom: 1px solid var(--gray-200);
      box-shadow: var(--shadow-sm);
      transform: translateY(-120%);
      opacity: 0;
      pointer-events: none;
      transition: transform .28s ease, opacity .28s ease;
      z-index: 25;
    }

    .mobile-drawer.open {
      transform: translateY(0);
      opacity: 1;
      pointer-events: auto;
    }

    .mobile-drawer nav {
      width: var(--container);
      margin: 0 auto;
      display: grid;
      gap: .25rem;
      padding: 1rem 0 1.2rem;
    }

    .mobile-drawer a {
      padding: .75rem;
      border-radius: 10px;
      font-weight: 600;
      color: var(--navy-700);
    }

    .mobile-drawer a:hover,
    .mobile-drawer a:focus-visible { background: var(--gray-100); }

    .hero {
      background: linear-gradient(165deg, rgba(180,35,35,.08), rgba(16,42,67,.05));
      padding: 5rem 0 4rem;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1.1fr .9fr;
      gap: 2rem;
      align-items: center;
    }

    .eyebrow {
      display: inline-block;
      font-weight: 700;
      color: var(--red-700);
      background: rgba(198,40,40,.1);
      padding: .3rem .7rem;
      border-radius: 999px;
      margin-bottom: .85rem;
      font-size: .9rem;
    }

    .hero h1 { font-size: clamp(2rem, 4vw, 3.35rem); }
    .hero p { font-size: 1.08rem; color: var(--gray-600); max-width: 62ch; }

    .hero-actions {
      display: flex;
      gap: .8rem;
      flex-wrap: wrap;
      margin-top: 1.3rem;
    }

    .hero-image {
      border-radius: var(--radius);
      min-height: 360px;
      overflow: hidden;
      box-shadow: var(--shadow-md);
      position: relative;
      background: var(--gray-200);
    }

    .hero-image img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
    }

    section { padding: 4.5rem 0; }
    .section-head { max-width: 68ch; margin-bottom: 2rem; }

    .mission {
      background: var(--gray-50);
      border-top: 1px solid var(--gray-200);
      border-bottom: 1px solid var(--gray-200);
    }

    .mission-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1.5rem;
    }

    .card {
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      padding: 1.25rem;
      box-shadow: var(--shadow-sm);
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1rem;
    }

    .stat-card {
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      padding: 1.2rem;
      background: var(--white);
      text-align: center;
    }

    .stat-value {
      font-size: clamp(1.8rem, 3vw, 2.4rem);
      font-weight: 900;
      color: var(--red-700);
      margin-bottom: .3rem;
    }

    .accordion-item {
      border: 1px solid var(--gray-200);
      border-radius: 12px;
      margin-bottom: .85rem;
      overflow: hidden;
      background: var(--white);
    }

    .accordion-trigger {
      width: 100%;
      border: 0;
      padding: 1rem 1.2rem;
      background: var(--white);
      text-align: left;
      font-weight: 750;
      font-size: 1rem;
      color: var(--navy-900);
      display: flex;
      justify-content: space-between;
      align-items: center;
      cursor: pointer;
    }

    .accordion-trigger .chev { transition: transform .22s ease; }
    .accordion-trigger[aria-expanded="true"] .chev { transform: rotate(180deg); }

    .accordion-panel {
      max-height: 0;
      overflow: hidden;
      transition: max-height .3s ease;
      border-top: 1px solid transparent;
    }

    .accordion-panel .inner {
      padding: 0 1.2rem 1rem;
      color: var(--gray-600);
    }

    .accordion-item.open .accordion-panel {
      max-height: 220px;
      border-top-color: var(--gray-200);
    }

    .involved-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1rem;
    }

    .news-wrap {
      position: relative;
      overflow: hidden;
    }

    .news-track {
      display: flex;
      transition: transform .35s ease;
    }

    .news-slide {
      min-width: 100%;
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 1rem;
    }

    .news-card img {
      width: 100%;
      height: 150px;
      object-fit: cover;
      border-radius: 10px;
      margin-bottom: .8rem;
    }

    .news-controls {
      margin-top: 1rem;
      display: flex;
      gap: .6rem;
    }

    .news-btn {
      border: 1px solid var(--gray-200);
      background: var(--white);
      width: 42px;
      height: 42px;
      border-radius: 999px;
      cursor: pointer;
      font-size: 1.25rem;
      color: var(--navy-900);
    }

    .donate-cta {
      background: var(--navy-900);
      color: var(--white);
    }

    .donate-cta h2, .donate-cta p { color: var(--white); }

    .donation-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: .75rem;
      margin: 1.2rem 0;
    }

    .amount {
      border: 1px solid rgba(255,255,255,.36);
      background: transparent;
      color: var(--white);
      border-radius: 10px;
      padding: .75rem;
      font-weight: 700;
      cursor: pointer;
      text-align: center;
    }

    .amount:hover,
    .amount.active { background: rgba(255,255,255,.15); }

    footer {
      padding: 3rem 0;
      background: var(--gray-50);
      border-top: 1px solid var(--gray-200);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 1.2fr repeat(4, 1fr);
      gap: 1rem;
    }

    .footer-col h3 { font-size: 1rem; margin-bottom: .8rem; }
    .footer-col a { display: block; margin-bottom: .45rem; color: var(--gray-600); }

    .modal-backdrop {
      position: fixed;
      inset: 0;
      background: rgba(16,42,67,.58);
      display: none;
      align-items: center;
      justify-content: center;
      padding: 1rem;
      z-index: 60;
    }

    .modal-backdrop.open { display: flex; }

    .modal {
      width: min(560px, 100%);
      background: var(--white);
      border-radius: 16px;
      padding: 1.2rem;
      box-shadow: var(--shadow-md);
    }

    .modal-top {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      margin-bottom: .8rem;
    }

    .close-modal {
      border: 1px solid var(--gray-200);
      background: var(--white);
      border-radius: 999px;
      width: 34px;
      height: 34px;
      cursor: pointer;
      font-size: 1.1rem;
    }

    .amount-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: .6rem;
      margin: .9rem 0;
    }

    .amount-grid button {
      border: 1px solid var(--gray-200);
      background: var(--white);
      border-radius: 10px;
      padding: .75rem;
      font-weight: 700;
      cursor: pointer;
    }

    .amount-grid button.active {
      background: var(--red-700);
      color: var(--white);
      border-color: var(--red-700);
    }

    .form-row {
      display: grid;
      gap: .4rem;
      margin-bottom: .8rem;
    }

    .form-row input {
      border: 1px solid var(--gray-200);
      border-radius: 10px;
      padding: .7rem .8rem;
      font: inherit;
    }

    .small { color: var(--gray-600); font-size: .93rem; }

    @media (max-width: 960px) {
      .desktop-nav { display: none; }
      .menu-toggle { display: inline-flex; }
      .hero-grid,
      .mission-grid,
      .stats-grid,
      .involved-grid,
      .news-slide,
      .footer-grid,
      .donation-grid {
        grid-template-columns: 1fr;
      }
      .hero { padding-top: 3.7rem; }
      section { padding: 3.2rem 0; }
      .news-card img { height: 180px; }
    }
  </style>
</head>
<body>
  <header class="topbar">
    <div class="container header-row">
      <a class="brand" href="#top" aria-label="Global Aid Alliance home">
        <span class="brand-mark" aria-hidden="true">GA</span>
        <span>Global Aid Alliance</span>
      </a>

      <nav class="desktop-nav" aria-label="Primary">
        <a href="#mission">About Us</a>
        <a href="#programs">Disaster Relief</a>
        <a href="#programs">Programs</a>
        <a href="#involved">Volunteer</a>
        <a href="#news">News</a>
        <a href="#footer">Find Local Chapter</a>
        <button class="btn btn-primary" id="headerDonate">Donate</button>
      </nav>

      <button class="menu-toggle" id="menuToggle" aria-expanded="false" aria-controls="mobileDrawer" aria-label="Open navigation menu">
        <span></span>
      </button>
    </div>

    <div class="mobile-drawer" id="mobileDrawer">
      <nav>
        <a href="#mission">About Us</a>
        <a href="#programs">Disaster Relief</a>
        <a href="#programs">Programs</a>
        <a href="#involved">Volunteer</a>
        <a href="#news">News</a>
        <a href="#footer">Find Local Chapter</a>
        <button class="btn btn-primary" id="mobileDonate">Donate</button>
      </nav>
    </div>
  </header>

  <main id="top">
    <section class="hero">
      <div class="container hero-grid">
        <div>
          <span class="eyebrow">Together We Respond</span>
          <h1>Rapid relief. Lasting resilience. Global solidarity in every emergency.</h1>
          <p>Global Aid Alliance delivers disaster relief, emergency assistance, and preparedness support in communities facing crisis. We work with local partners to save lives today and rebuild safer futures for tomorrow.</p>
          <div class="hero-actions">
            <button class="btn btn-primary" id="heroDonate">Donate Now</button>
            <a class="btn btn-secondary" href="#involved">Become a Volunteer</a>
          </div>
        </div>
        <figure class="hero-image">
          <img src="https://images.unsplash.com/photo-1582213782179-e0d53f98f2ca?auto=format&fit=crop&w=1200&q=80" alt="Relief workers distributing aid supplies to families in a disaster-affected community" loading="lazy" />
        </figure>
      </div>
    </section>

    <section class="mission" id="mission">
      <div class="container">
        <div class="section-head">
          <h2>Our Mission</h2>
          <p>We prevent suffering, protect dignity, and strengthen community resilience before, during, and after disasters. Through fast response and long-term recovery partnerships, we ensure help reaches people when it matters most.</p>
        </div>
        <div class="mission-grid">
          <article class="card">
            <h3>What We Do</h3>
            <p>Emergency shelter, food, clean water, health support, blood donation mobilization, and preparedness training in vulnerable regions.</p>
          </article>
          <article class="card">
            <h3>How We Work</h3>
            <p>Locally led response, transparent financial stewardship, and evidence-driven programs that build safer, stronger communities.</p>
          </article>
        </div>
      </div>
    </section>

    <section id="impact">
      <div class="container">
        <div class="section-head">
          <h2>Impact at a Glance</h2>
          <p>Trusted by donors and communities worldwide, our humanitarian network delivers measurable results across crises and recovery efforts.</p>
        </div>
        <div class="stats-grid" aria-label="Impact statistics">
          <article class="stat-card">
            <div class="stat-value" data-target="12" data-suffix="M">0</div>
            <p>People Helped</p>
          </article>
          <article class="stat-card">
            <div class="stat-value" data-target="50000" data-format="comma">0</div>
            <p>Volunteers Mobilized</p>
          </article>
          <article class="stat-card">
            <div class="stat-value" data-target="190">0</div>
            <p>Countries Supported</p>
          </article>
          <article class="stat-card">
            <div class="stat-value" data-target="850" data-prefix="$" data-suffix="M">0</div>
            <p>Raised for Relief</p>
          </article>
        </div>
      </div>
    </section>

    <section id="programs" class="mission">
      <div class="container">
        <div class="section-head">
          <h2>Programs and Services</h2>
          <p>Explore the core programs that power our emergency response and community resilience work.</p>
        </div>

        <div class="accordion" id="programAccordion">
          <article class="accordion-item open">
            <button class="accordion-trigger" aria-expanded="true">Disaster Relief <span class="chev">⌄</span></button>
            <div class="accordion-panel">
              <div class="inner">Rapid deployment teams provide shelter, food, water, and emergency support after hurricanes, floods, earthquakes, and wildfires.</div>
            </div>
          </article>
          <article class="accordion-item">
            <button class="accordion-trigger" aria-expanded="false">Blood Donation <span class="chev">⌄</span></button>
            <div class="accordion-panel">
              <div class="inner">We coordinate national blood drives and emergency blood supply logistics to support hospitals during routine and crisis periods.</div>
            </div>
          </article>
          <article class="accordion-item">
            <button class="accordion-trigger" aria-expanded="false">Emergency Preparedness <span class="chev">⌄</span></button>
            <div class="accordion-panel">
              <div class="inner">Preparedness workshops, risk education, and local response planning help communities reduce harm before disasters strike.</div>
            </div>
          </article>
          <article class="accordion-item">
            <button class="accordion-trigger" aria-expanded="false">International Humanitarian Aid <span class="chev">⌄</span></button>
            <div class="accordion-panel">
              <div class="inner">Cross-border support for displacement crises includes emergency relief kits, health outreach, and recovery grants.</div>
            </div>
          </article>
          <article class="accordion-item">
            <button class="accordion-trigger" aria-expanded="false">Community Health <span class="chev">⌄</span></button>
            <div class="accordion-panel">
              <div class="inner">Community health initiatives strengthen local clinics, deliver essential services, and improve long-term well-being.</div>
            </div>
          </article>
        </div>
      </div>
    </section>

    <section id="involved">
      <div class="container">
        <div class="section-head">
          <h2>Get Involved</h2>
          <p>Your time, voice, and support can help communities recover faster and prepare better for future emergencies.</p>
        </div>
        <div class="involved-grid">
          <article class="card"><h3>Volunteer</h3><p>Join local response teams, blood drives, and preparedness events in your community.</p></article>
          <article class="card"><h3>Start a Fundraiser</h3><p>Mobilize your network with a campaign that directly supports active response operations.</p></article>
          <article class="card"><h3>Corporate Partnerships</h3><p>Partner with us through sponsorships, employee volunteering, and emergency grants.</p></article>
        </div>
      </div>
    </section>

    <section id="news" class="mission">
      <div class="container">
        <div class="section-head">
          <h2>Latest News</h2>
          <p>Current updates from relief operations, volunteer stories, and preparedness initiatives.</p>
        </div>

        <div class="news-wrap">
          <div class="news-track" id="newsTrack">
            <div class="news-slide">
              <article class="card news-card">
                <img src="https://images.unsplash.com/photo-1618477247222-acbdb0e159b3?auto=format&fit=crop&w=1000&q=80" alt="Emergency teams coordinating hurricane response logistics" loading="lazy" />
                <h3>Hurricane Response Update</h3>
                <p>Field teams have delivered emergency shelter kits and clean water to coastal families impacted by severe storms.</p>
              </article>
              <article class="card news-card">
                <img src="https://images.unsplash.com/photo-1472145246862-b24cf25c4a36?auto=format&fit=crop&w=1000&q=80" alt="Volunteers assisting wildfire evacuation and relief operations" loading="lazy" />
                <h3>Wildfire Relief Efforts</h3>
                <p>Volunteers are supporting evacuation centers with meals, medical support, and overnight accommodations.</p>
              </article>
            </div>
            <div class="news-slide">
              <article class="card news-card">
                <img src="https://images.unsplash.com/photo-1581594693702-fbdc51b2763b?auto=format&fit=crop&w=1000&q=80" alt="Community blood donation campaign at a regional center" loading="lazy" />
                <h3>Blood Drive Campaign</h3>
                <p>Our nationwide campaign is expanding blood access for hospitals ahead of peak emergency season.</p>
              </article>
              <article class="card news-card">
                <img src="https://images.unsplash.com/photo-1521737604893-d14cc237f11d?auto=format&fit=crop&w=1000&q=80" alt="Dedicated volunteer recognized for sustained disaster response support" loading="lazy" />
                <h3>Volunteer Spotlight</h3>
                <p>Meet the volunteer leaders helping train new responders and strengthen neighborhood readiness.</p>
              </article>
            </div>
          </div>
        </div>
        <div class="news-controls" aria-label="News carousel controls">
          <button class="news-btn" id="newsPrev" aria-label="Previous news stories">←</button>
          <button class="news-btn" id="newsNext" aria-label="Next news stories">→</button>
        </div>
      </div>
    </section>

    <section class="donate-cta" id="donate">
      <div class="container">
        <h2>Your support saves lives today.</h2>
        <p>91 cents of every dollar goes directly to humanitarian services. Help deliver urgent aid, preparedness training, and recovery support to communities in crisis.</p>
        <div class="donation-grid" aria-label="Suggested donation amounts">
          <button class="amount">$25 · 5 emergency blankets</button>
          <button class="amount">$50 · Food & water for a week</button>
          <button class="amount">$100 · Shelter materials</button>
          <button class="amount">$250 · Train one volunteer</button>
          <button class="amount">Custom amount</button>
        </div>
        <button class="btn btn-primary" id="ctaDonate">Donate Now</button>
      </div>
    </section>
  </main>

  <footer id="footer">
    <div class="container footer-grid">
      <div>
        <h3>Global Aid Alliance</h3>
        <p class="small">Together We Respond</p>
        <p class="small">© 2024 Global Aid Alliance. All rights reserved.<br/>A 501(c)(3) nonprofit organization. Tax ID: 53-0196742</p>
      </div>
      <div class="footer-col">
        <h3>Programs</h3>
        <a href="#programs">Disaster Relief</a>
        <a href="#programs">Blood Donation</a>
        <a href="#programs">Emergency Preparedness</a>
        <a href="#programs">International Aid</a>
        <a href="#programs">Community Health</a>
      </div>
      <div class="footer-col">
        <h3>Get Involved</h3>
        <a href="#involved">Volunteer</a>
        <a href="#donate">Donate</a>
        <a href="#involved">Start a Fundraiser</a>
        <a href="#involved">Corporate Partnerships</a>
      </div>
      <div class="footer-col">
        <h3>About</h3>
        <a href="#mission">Our Mission</a>
        <a href="#mission">Leadership</a>
        <a href="#impact">Financials</a>
        <a href="#mission">Careers</a>
        <a href="#news">Press Room</a>
      </div>
      <div class="footer-col">
        <h3>Support</h3>
