  <script>
    const drawer = document.getElementById('mobileDrawer');
    const menuToggle = document.getElementById('menuToggle');

    menuToggle.addEventListener('click', () => {
      const open = drawer.classList.toggle('open');
      menuToggle.setAttribute('aria-expanded', String(open));
    });

    drawer.querySelectorAll('a, button').forEach((el) => {
      el.addEventListener('click', () => {
        drawer.classList.remove('open');
        menuToggle.setAttribute('aria-expanded', 'false');
      });
    });

    const modal = document.getElementById('donationModal');
    const openDonateButtons = ['heroDonate', 'headerDonate', 'mobileDonate', 'ctaDonate']
      .map((id) => document.getElementById(id))
      .filter(Boolean);

    const closeModal = () => {
      modal.classList.remove('open');
      document.body.style.overflow = '';
    };

    const openModal = () => {
      modal.classList.add('open');
      document.body.style.overflow = 'hidden';
    };

    openDonateButtons.forEach((btn) => btn.addEventListener('click', openModal));
    document.getElementById('closeModal').addEventListener('click', closeModal);

    modal.addEventListener('click', (event) => {
      if (event.target === modal) closeModal();
    });

    const amountButtons = Array.from(document.querySelectorAll('#amountGrid button'));
    const customAmountInput = document.getElementById('customAmount');
    let selectedAmount = '50';

    amountButtons.forEach((btn) => {
      if (btn.dataset.value === selectedAmount) btn.classList.add('active');
      btn.addEventListener('click', () => {
        amountButtons.forEach((button) => button.classList.remove('active'));
        btn.classList.add('active');
        selectedAmount = btn.dataset.value;
        if (selectedAmount !== 'custom') customAmountInput.value = '';
      });
    });

    document.getElementById('submitDonation').addEventListener('click', () => {
      const email = document.getElementById('email').value.trim();
      const customValue = customAmountInput.value.trim();
      const status = document.getElementById('donationStatus');
      const amount = selectedAmount === 'custom' ? customValue : selectedAmount;

      if (!amount || Number(amount) <= 0) {
        status.textContent = 'Please choose or enter a valid donation amount.';
        return;
      }

      if (!email.includes('@')) {
        status.textContent = 'Please enter a valid email address to continue.';
        return;
      }

      status.textContent = `Thank you! Your $${amount} donation intent has been recorded.`;
    });

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') closeModal();
    });

    const track = document.getElementById('newsTrack');
    const slides = track.children.length;
    let currentSlide = 0;

    const renderSlide = () => {
      track.style.transform = `translateX(-${currentSlide * 100}%)`;
    };

    document.getElementById('newsPrev').addEventListener('click', () => {
      currentSlide = (currentSlide - 1 + slides) % slides;
      renderSlide();
    });

    document.getElementById('newsNext').addEventListener('click', () => {
      currentSlide = (currentSlide + 1) % slides;
      renderSlide();
    });

    document.querySelectorAll('.accordion-trigger').forEach((trigger) => {
      trigger.addEventListener('click', () => {
        const item = trigger.closest('.accordion-item');
        const expanded = trigger.getAttribute('aria-expanded') === 'true';
        trigger.setAttribute('aria-expanded', String(!expanded));
        item.classList.toggle('open', !expanded);
      });
    });

    const counters = document.querySelectorAll('.stat-value');
    const formatNumber = (value, comma) => comma ? new Intl.NumberFormat().format(value) : value;

    const animateCounter = (entry) => {
      const target = Number(entry.dataset.target || 0);
      const suffix = entry.dataset.suffix || '';
      const prefix = entry.dataset.prefix || '';
      const useComma = entry.dataset.format === 'comma';
      const startTime = performance.now();
      const duration = 1400;

      const frame = (now) => {
        const progress = Math.min((now - startTime) / duration, 1);
        const eased = 1 - Math.pow(1 - progress, 3);
        const current = Math.floor(target * eased);
        entry.textContent = `${prefix}${formatNumber(current, useComma)}${suffix}`;
        if (progress < 1) requestAnimationFrame(frame);
      };

      requestAnimationFrame(frame);
    };

    const observer = new IntersectionObserver((items, obs) => {
      items.forEach((item) => {
        if (item.isIntersecting) {
          animateCounter(item.target);
          obs.unobserve(item.target);
        }
      });
    }, { threshold: 0.35 });

    counters.forEach((counter) => observer.observe(counter));
  </script>
